tinymce.PluginManager.add('dbrepo', function (editor, url) {

  editor.addCommand("cmdDBRepo", function () {
    editor.windowManager.openUrl({
      title: "DBRepo",
      url: RS.withCacheVersion(url + "/dialog.html"),
      width: 1200,
      height: 1000,
      buttons: [
        { type: "cancel", id: "close", name: "close", text: "Close" },
        { type: "custom", id: "insertRows", name: "insertRows", text: "Insert rows", disabled: true },
        { type: "custom", id: "insert", name: "insert", text: "Insert link", primary: true, disabled: true }
      ],
      onAction(dialogApi, button) {
        if (button.name === "insert") {
          editor.fire("dbrepo-insert");
        } else if (button.name === "insertRows") {
          editor.fire("dbrepo-insert-rows");
        }
      },
      onMessage(dialogApi, details) {
        const $insertButton = $("button[title='Insert link']");
        const $insertRowsButton = $("button[title='Insert rows']");
        if (details.mceAction === "enable") {
          $insertButton.prop("disabled", null);
          $insertButton.removeAttr("disabled");
        } else if (details.mceAction === "disable") {
          $insertButton.attr("disabled", "disabled");
        }
        if (details.rowsAction === "enable") {
          $insertRowsButton.prop("disabled", null);
          $insertRowsButton.removeAttr("disabled");
        } else if (details.rowsAction === "disable") {
          $insertRowsButton.attr("disabled", "disabled");
        }
      }
    });
  });

  editor.ui.registry.addButton('dbrepo', {
    icon: 'dbrepo',
    tooltip: 'DBRepo',
    onAction: function () {
      editor.execCommand("cmdDBRepo");
    }
  });

  editor.ui.registry.addMenuItem('optDBRepo', {
    text: 'DBRepo',
    icon: 'dbrepo',
    onAction: function () { editor.execCommand("cmdDBRepo"); },
  });

  if (!window.insertActions) window.insertActions = new Map();
  window.insertActions.set("optDBRepo", {
    text: 'DBRepo',
    icon: 'dbrepo',
    action: () => {
      editor.execCommand("cmdDBRepo");
    },
  });
});
